func TestConcurrentRequestsAreCounted(t *testing.T) {
	s := fakenexus.New(t, pick(t, "catalog-group-connector-30482--anon")...)
	const n = 20
	var wg sync.WaitGroup
	for range n {
		wg.Go(func() {
			req, err := http.NewRequest(http.MethodGet, s.URL(hostGroup)+"/v2/_catalog", nil)
			if err != nil {
				t.Error(err)
				return
			}
			r, err := http.DefaultClient.Do(req)
			if err != nil {
				t.Error(err)
				return
			}
			_, _ = io.Copy(io.Discard, r.Body)
			r.Body.Close()
		})
	}
	wg.Wait()
	if got := s.Hits("catalog-group-connector-30482--anon"); got != n {
		t.Errorf("Hits = %d, want %d", got, n)
	}
}

func TestServersAreClosedWithTheTest(t *testing.T) {
	var base string
	t.Run("lifetime", func(t *testing.T) {
		s := fakenexus.New(t, pick(t, "catalog-group-connector-30482--anon")...)
		base = s.URL(hostGroup)
		if r, _ := get(t, base, "/v2/_catalog", nexusfixture.Anonymous); r.StatusCode != http.StatusOK {
			t.Fatalf("status = %d while the test runs", r.StatusCode)
		}
	})
	// The sub-test is over: its Cleanup closed the server, the port refuses.
	client := &http.Client{Transport: &http.Transport{DisableKeepAlives: true}}
	if r, err := client.Get(base + "/v2/_catalog"); err == nil {
		r.Body.Close()
		t.Errorf("the server still answers after its test ended (status %d)", r.StatusCode)
	}
}

